function validate([baseCosts, toppingCosts, target]) {
  if (baseCosts.length < 1 || baseCosts.length > 10) return 'baseCosts needs 1 to 10 prices.';
  if (toppingCosts.length < 1 || toppingCosts.length > 10) return 'toppingCosts needs 1 to 10 prices.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 10000;
  if (!baseCosts.every(ok) || !toppingCosts.every(ok)) return 'Every price is an integer from 1 to 10^4.';
  if (!ok(target)) return 'target is an integer from 1 to 10^4.';
  return null;
}

