function closestCost(baseCosts, toppingCosts, target) {
  let best = baseCosts[0];

  function explore(index, cost) {
    const gap = Math.abs(cost - target);
    const bestGap = Math.abs(best - target);
    if (gap < bestGap || (gap === bestGap && cost < best)) {
      best = cost;
    }
    if (cost >= target || index === toppingCosts.length) {
      return;
    }
    explore(index + 1, cost);
    explore(index + 1, cost + toppingCosts[index]);
    explore(index + 1, cost + 2 * toppingCosts[index]);
  }

  for (const base of baseCosts) {
    explore(0, base);
  }
  return best;
}

