function closestCost(baseCosts, toppingCosts, target) {
  let sums = new Set([0]);
  for (const t of toppingCosts) {
    const next = new Set();
    for (const s of sums) { next.add(s); next.add(s + t); next.add(s + 2 * t); }
    sums = next;
  }
  let answer = null;
  for (const b of baseCosts)
    for (const s of sums) {
      const c = b + s;
      if (answer === null) { answer = c; continue; }
      const d = Math.abs(c - target), e = Math.abs(answer - target);
      if (d < e || (d === e && c < answer)) answer = c;
    }
  return answer;
}

