function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const cap = rand() < 0.5 ? 10000 : int(50, 2000);
    const baseCosts = Array.from({ length: 10 }, () => int(1, cap));
    const toppingCosts = Array.from({ length: 10 }, () => int(1, cap));
    return [baseCosts, toppingCosts, int(1, 10000)];
  }
  const cap = rand() < 0.3 ? 5 : 30;
  const baseCosts = Array.from({ length: int(1, 4) }, () => int(1, cap));
  const toppingCosts = Array.from({ length: int(1, 4) }, () => int(1, cap));
  return [baseCosts, toppingCosts, int(1, 4 * cap)];
}
